import { Object3D, Mesh, PlaneGeometry, Group, Color, Vector3 } from 'three/webgpu';
import {
	MeshStandardNodeMaterial,
	MeshBasicNodeMaterial,
	color,
	mix,
	position,
	float,
} from 'three/tsl';
import { gsap } from 'gsap';
import primitives from '@/primitives';
import { createTextMesh } from '@/text';

/**
 * @typedef {object} NodeConfig
 * @property {Array<{text:string,role:string}>} textContent
 */

/**
 * @typedef {object} NodeContext
 * @property {object} fontAtlas - utility with a createText method
 * @property {object} textureLoader
 * @property {object} glbLoader
 * @property {object} primitives - map of cinematic primitives
 */

export default function createNode(config, ctx) {
	const root = new Object3D();
	root.position.set(0, 0, 0);
	root.rotation.set(0, 0, 0);
	root.scale.set(1, 1, 1);

	/* --------------------------------------------------------------------
	 * Rail – floating machined‑metal background
	 * -------------------------------------------------------------------- */
	const railWidth = 3.6;
	const railHeight = 0.5;
	const railGeom = new PlaneGeometry(railWidth, railHeight);
	const railMat = new MeshStandardNodeMaterial();

	// vertical gradient albedo (top → bottom)
	const top = color('#1b1b23');
	const bottom = color('#101015');
	railMat.colorNode = mix(top, bottom, position.y.add(1).div(2));
	railMat.metalnessNode = float(0.5);
	railMat.roughnessNode = float(0.55);
	railMat.clearcoatNode = float(0.2);
	railMat.anisotropyNode = float(0.6);
	// slight specular edge – approximated by clearcoatRoughness
	railMat.clearcoatRoughnessNode = float(0.1);

	const rail = new Mesh(railGeom, railMat);
	rail.position.set(0, 0, 0.15);
	root.add(rail);

	/* --------------------------------------------------------------------
	 * Contact shadow beneath the rail
	 * -------------------------------------------------------------------- */
	const shadowGeom = new PlaneGeometry(railWidth, railHeight);
	const shadowMat = new MeshBasicNodeMaterial({
		color: new Color(0x000000),
		transparent: true,
		opacity: 0.35,
	});
	const shadow = new Mesh(shadowGeom, shadowMat);
	shadow.position.set(0, -0.06, 0);
	root.add(shadow);

	/* --------------------------------------------------------------------
	 * Underline – active entry indicator
	 * -------------------------------------------------------------------- */
	const underlineW = 0.28;
	const underlineH = 0.025;
	const underlineGeom = new PlaneGeometry(underlineW, underlineH);
	const underlineMat = new MeshStandardNodeMaterial({
		color: new Color('#ff2a38'),
		emissive: new Color('#ff2a38'),
		emissiveIntensity: 1.8,
		transparent: true,
	});
	const underline = new Mesh(underlineGeom, underlineMat);
	// placed just below baseline of the text row
	underline.position.set(-1.36, -0.18, 0.001);
	root.add(underline);

	/* --------------------------------------------------------------------
	 * Navigation entries
	 * -------------------------------------------------------------------- */
	const entries = [
		{ label: 'HOME', role: 'nav-active' },
		{ label: 'FEATURES', role: 'nav-item' },
		{ label: 'COLLECTION', role: 'nav-item' },
		{ label: 'PRICING', role: 'nav-item' },
		{ label: 'JOURNAL', role: 'nav-item' },
	];

	const spacing = 0.68;
	const startX = -(spacing * (entries.length - 1)) / 2;

	const entryGroups = [];
	const gsapTimelines = [];

	let activeIndex = 0;

	entries.forEach((entry, i) => {
		const group = new Group();
		const x = startX + i * spacing;
		group.position.set(x, 0, 0);

		/* hit cell – invisible but receives pointer events */
		const cellGeom = new PlaneGeometry(0.6, 0.34);
		const cellMat = new MeshBasicNodeMaterial({ transparent: true, opacity: 0 });
		const cell = new Mesh(cellGeom, cellMat);
		group.add(cell);

		/* text mesh – MSDF rendered via fontAtlas */
		const isActive = i === activeIndex;
		const txtColor = isActive ? '#e8ecf2' : '#a6adba';
		const txtWeight = isActive ? 700 : 400;
		const txtMesh = createTextMesh({
			text: entry.label,
			fontSize: 13,
			fontWeight: txtWeight,
			color: new Color(txtColor),
			fontFamily: 'JetBrains Mono',
			atlas: ctx.fontAtlas,
		});
		txtMesh.position.set(0, 0, 0.01);
		group.add(txtMesh);

		/* interaction handlers */
		const baseColor = new Color(txtColor);
		const hoverColor = new Color('#e8ecf2');

		const hoverTimeline = gsap.timeline({ paused: true });
		const pressTimeline = gsap.timeline({ paused: true });

		const handlers = {
			pointerenter: () => {
				hoverTimeline.clear();
				hoverTimeline.to(baseColor, {
					r: hoverColor.r,
					g: hoverColor.g,
					b: hoverColor.b,
					duration: 0.16,
					ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
					onUpdate: () => {
						txtMesh.material.color.copy(baseColor);
					},
				});
				hoverTimeline.play();
			},
			pointerleave: () => {
				hoverTimeline.clear();
				hoverTimeline.to(baseColor, {
					r: isActive ? new Color('#e8ecf2').r : new Color('#a6adba').r,
					g: isActive ? new Color('#e8ecf2').g : new Color('#a6adba').g,
					b: isActive ? new Color('#e8ecf2').b : new Color('#a6adba').b,
					duration: 0.16,
					ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
					onUpdate: () => {
						txtMesh.material.color.copy(baseColor);
					},
				});
				hoverTimeline.play();
			},
			pointerdown: () => {
				pressTimeline.clear();
				pressTimeline.to(group.scale, {
					x: 0.97,
					y: 0.97,
					z: 0.97,
					duration: 0.12,
					ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
				});
				pressTimeline.to(
					group.position,
					{ z: -0.03, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' },
					0
				);
				pressTimeline.play();
			},
			pointerup: () => {
				pressTimeline.clear();
				pressTimeline.to(group.scale, {
					x: 1,
					y: 1,
					z: 1,
					duration: 0.12,
					ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
				});
				pressTimeline.to(
					group.position,
					{ z: 0, duration: 0.12, ease: 'cubic-bezier(0.175,0.885,0.32,1.275)' },
					0
				);
				pressTimeline.play();
			},
			click: () => {
				if (activeIndex !== i) {
					setActive(i);
					if (root.userData && root.userData.handlers && root.userData.handlers.navigate) {
						root.userData.handlers.navigate(entry.label.toLowerCase());
					}
				}
			},
		};

		group.userData.handlers = handlers;
		gsapTimelines.push(hoverTimeline, pressTimeline);
		entryGroups.push({ group, txtMesh, isActive, baseColor });
		root.add(group);
	});

	/* --------------------------------------------------------------------
	 * Helper – switch active entry
	 * -------------------------------------------------------------------- */
	function setActive(idx) {
		if (idx === activeIndex) return;

		const prev = entryGroups[activeIndex];
		const next = entryGroups[idx];

		/* previous becomes inactive */
		prev.isActive = false;
		prev.baseColor.set('#a6adba');
		prev.txtMesh.material.color.copy(prev.baseColor);

		/* new becomes active */
		next.isActive = true;
		next.baseColor.set('#e8ecf2');
		next.txtMesh.material.color.copy(next.baseColor);

		/* move underline */
		const targetX = startX + idx * spacing;
		const underlineTL = gsap.timeline();
		underlineTL.to(underline.position, {
			x: targetX,
			duration: 0.26,
			ease: 'cubic-bezier(0.165,0.84,0.44,1)',
		});
		underlineTL.fromTo(
			underline.scale,
			{ x: 1 },
			{ x: 1.04, duration: 0.09, ease: 'power4.out' },
			0
		);
		underlineTL.to(
			underline.scale,
			{ x: 1, duration: 0.09, ease: 'power4.out' },
			0.09
		);
		gsapTimelines.push(underlineTL);

		activeIndex = idx;
	}

	/* --------------------------------------------------------------------
	 * Mount animation (rise‑in)
	 * -------------------------------------------------------------------- */
	gsap.from(root.position, {
		y: 0.4,
		duration: 0.7,
		ease: 'power3.out',
	});

	/* --------------------------------------------------------------------
	 * UserData – public API and cleanup
	 * -------------------------------------------------------------------- */
	root.userData.handlers = {
		/** external consumer may replace this to react to navigation clicks */
		navigate: (target) => {},
	};
	root.userData.setActive = setActive;
	root.userData.cleanup = () => {
		gsapTimelines.forEach((t) => t.kill());
		gsap.killTweensOf(root);
		rail.geometry.dispose();
		rail.material.dispose();
		shadow.geometry.dispose();
		shadow.material.dispose();
		underline.geometry.dispose();
		underline.material.dispose();
		entryGroups.forEach(({ group }) => {
			group.traverse((obj) => {
				if (obj.geometry) obj.geometry.dispose();
				if (obj.material) obj.material.dispose();
			});
		});
	};

	return root;
}
